function realCalendarLookup(){
  const holidays = [];
  const pDates = {}, tDates = {};
  SEED_SPLITUP.forEach(([date,psr,tsr,holiday])=>{
    if(holiday){ holidays.push({date, label:holiday}); return; }
    if(psr!=null && !(psr in pDates)) pDates[psr]=date;
    if(tsr!=null && !(tsr in tDates)) tDates[tsr]=date;
  });
  return {holidays, pDates, tDates};
}

