let DATA = null;
let SESSION = null;

function loadData(){
  const raw = localStorage.getItem(STORAGE_KEY);
  DATA = raw ? JSON.parse(raw) : defaultData();
  // migrate: ensure new top-level AND nested meta fields exist if an older backup loaded
  const d = defaultData();
  for(const k in d){
    if(!(k in DATA)){ DATA[k]=d[k]; continue; }
    if(k==="meta"){
      for(const mk in d.meta){ if(!(mk in DATA.meta)) DATA.meta[mk]=d.meta[mk]; }
    }
  }
  if(!Array.isArray(DATA.modules)) DATA.modules=[];
  DATA.modules.forEach((m,i)=>{ if(!m.id)m.id=uid(); if(!m.code)m.code=`M${String(i+1).padStart(2,"0")}`; if(!Array.isArray(m.topics))m.topics=[]; });
  if(!Array.isArray(DATA.users) || !DATA.users.length){
    DATA.users=[
      {id:"admin-principal", username:"principal", name:"Principal", role:"principal", pin:DATA.meta.principalPin||"5678", active:true},
      {id:"inst-durgesh", username:"durgesh", name:DATA.meta.instructor||"Durgesh Kadam", role:"instructor", pin:DATA.meta.instructorPin||"1234", active:true}
    ];
  }
  DATA.users.forEach(u=>{ if(!u.id)u.id=uid(); if(u.active===undefined)u.active=true; });
  // V14 safe migration: preserve a pre-upgrade snapshot before changing schema.
  const oldSchema=Number(DATA.meta.schemaVersion||1);
  if(oldSchema<14){
    try{ if(!localStorage.getItem("iti-v14-pre-upgrade-snapshot")) localStorage.setItem("iti-v14-pre-upgrade-snapshot",JSON.stringify({createdAt:new Date().toISOString(),schemaVersion:oldSchema,data:DATA})); }catch(e){}
    DATA.meta.schemaVersion=14; DATA.meta.appVersion="V14"; DATA.meta.migratedAt=new Date().toISOString();
  }

  // migrate: attach plan/materials to practicals & theory items saved before this feature existed,
  // and refresh plan content if it's from the older/generic parse (upgrade path to official DVET docs)
  if(!DATA.theory.length){
    DATA.theory = SEED_THEORY.map(t=>({no:t[0], title:t[1], status:"pending", doneDate:null, plannedDate:null,
      sequence:t[0], plan: PLAN_THEORY[t[0]] || null,
      materials:{pdfLink:"",youtubeLink:"",updatedDate:null}}));
  }
  DATA.practicals.forEach(p=>{
    if(!p.plan || !("questions" in p.plan)) p.plan = PLAN_DEMO[p.no] || p.plan || null;
    if(!("materials" in p)) p.materials = {pdfLink:"",youtubeLink:"",updatedDate:null};
    if(!("plannedDate" in p)) p.plannedDate = null;
    if(!("sequence" in p)) p.sequence = p.no;
    if(!("hours" in p)) p.hours = DEMO_HOURS[p.no]||7;
  });
  DATA.theory.forEach(t=>{
    if(!("plan" in t) || !t.plan) t.plan = PLAN_THEORY[t.no] || null;
    if(!("materials" in t)) t.materials = {pdfLink:"",youtubeLink:"",updatedDate:null};
    if(!("plannedDate" in t)) t.plannedDate = null;
    if(!("sequence" in t)) t.sequence = t.no;
  });
  DATA.trainees.forEach(t=>{
    if(!t.pin) t.pin = generatePin();
  });
  if(!DATA.meta.realCalendarApplied){
    const cal = realCalendarLookup();
    DATA.practicals.forEach(p=>{ if(cal.pDates[p.no]) p.plannedDate = cal.pDates[p.no]; });
    DATA.theory.forEach(t=>{ if(cal.tDates[t.no]) t.plannedDate = cal.tDates[t.no]; });
    cal.holidays.forEach(h=>{ if(!DATA.holidays.some(x=>x.date===h.date)) DATA.holidays.push(h); });
    DATA.holidays.sort((a,b)=>a.date.localeCompare(b.date));
    DATA.meta.realCalendarApplied = true;
    DATA.meta.scheduleMode = DATA.meta.scheduleMode || "real";
  }
  saveData();
}
function saveData(){
  if(DATA && DATA.meta){ DATA.meta.schemaVersion=14; DATA.meta.appVersion="V14"; }
  localStorage.setItem(STORAGE_KEY, JSON.stringify(DATA));
  if(window.CloudCenter) window.CloudCenter.scheduleSync();
}

function uid(){ return Math.random().toString(36).slice(2,9); }
function todayISO(){ return new Date().toISOString().slice(0,10); }
function safeDateRangeLoop(fromDate,toDate,maxDays=5000){
  const start=new Date(fromDate), end=new Date(toDate);
  if(Number.isNaN(start.getTime()) || Number.isNaN(end.getTime()) || start>end) return {start,end,valid:false};
  return {start,end,valid:true,maxDays};
}
function isHoliday(dateISO){ return DATA.holidays.some(h=>h.date===dateISO); }
function generatePin(){ return String(Math.floor(1000+Math.random()*9000)); }
function wrapTablesForScroll(){
  document.querySelectorAll("table.datatable").forEach(t=>{
    if(t.parentElement.classList.contains("table-scroll")) return;
    const wrap = document.createElement("div");
    wrap.className = "table-scroll";
    t.parentNode.insertBefore(wrap, t);
    wrap.appendChild(t);
  });
}

/* ===================== USER MANAGEMENT ===================== */
const Users = {
  render(){
    const el=document.getElementById("usersTable");
    if(!el) return;
    const users=(DATA.users||[]).filter(u=>u.role!=="student");
    el.innerHTML=users.map(u=>`
      <tr>
        <td><strong>${esc(u.name)}</strong></td>
        <td>${esc(u.username)}</td>
        <td><span class="badge">${esc(u.role)}</span></td>
        <td>${u.active===false?"<span class=\"badge danger\">Disabled</span>":"<span class=\"badge success\">Active</span>"}</td>
        <td>
          <button class="btn small" onclick="Users.resetPin('${u.id}')">Reset PIN</button>
          ${u.username!=="principal"?`<button class="btn small danger" onclick="Users.toggle('${u.id}')">${u.active===false?"Enable":"Disable"}</button>`:""}
        </td>
      </tr>`).join("");
  },
  create(){
    if(SESSION?.role!=="principal"){alert("Only Principal can create instructor accounts.");return;}
    const name=document.getElementById("newUserName").value.trim();
    const username=document.getElementById("newUserUsername").value.trim().toLowerCase().replace(/\s+/g,"");
    const pin=document.getElementById("newUserPin").value.trim();
    if(!name||!username||!pin){alert("Enter instructor name, User ID and PIN.");return;}
    if(pin.length<4){alert("PIN must be at least 4 digits.");return;}
    if((DATA.users||[]).some(u=>u.username.toLowerCase()===username)){alert("This User ID already exists.");return;}
    DATA.users.push({id:uid(),username,name,role:"instructor",pin,active:true,createdAt:todayISO()});
    saveData(); Users.render();
    document.getElementById("newUserName").value="";
    document.getElementById("newUserUsername").value="";
    document.getElementById("newUserPin").value="";
    alert(`Instructor account created.\n\nUser ID: ${username}\nPIN: ${pin}`);
  },
  resetPin(id){
    const u=DATA.users.find(x=>x.id===id); if(!u)return;
    const pin=prompt(`Enter new PIN for ${u.name}:`, generatePin());
    if(pin===null)return;
    if(pin.trim().length<4){alert("PIN must be at least 4 characters.");return;}
    u.pin=pin.trim(); saveData(); Users.render(); alert("PIN updated.");
  },
  toggle(id){
    const u=DATA.users.find(x=>x.id===id); if(!u || u.username==="principal")return;
    u.active=u.active===false; saveData(); Users.render();
  }
};



/* ===================== PRINT-READY RECORD FORMATS ===================== */
const RecordFormats = {
  profile() {
    const p = (typeof Inspection !== "undefined" && Inspection.load) ? Inspection.load() : {};
    const m = DATA.meta || {};
    return {
      name: p.name || m.instructor || "Durgesh Dnyandev Kadam",
      designation: p.designation || "Craft Instructor, DTP Trade",
      trade: m.trade || "Desktop Publishing Operator (DTPO)",
      batch: m.batch || "1st Year DTPO",
      session: m.session || "2026-27",
      institute: m.institute || "Bharat Ratna Dr. Babasaheb Ambedkar Government ITI, Mumbai-01"
    };
  },
  esc(v) {
    return String(v ?? "").replace(/[&<>"']/g, s => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[s]));
  },
  record(type, no) {
    const isDemo = type==="demo" || type==="practical";
    const list = isDemo ? (DATA.practicals||[]) : (DATA.theory||[]);
    const item = list.find(x=>Number(x.no)===Number(no)) || list[0] || {};
    const n = Number(no || item.no || 1);
    // Bundled 58/119 records are DTPO references only. Never reuse them for another trade.
    const isDtpTrade=/desktop publishing|dtpo|\bdtp\b/i.test(String(DATA.meta?.trade||""));
    const official = !isDtpTrade ? null : (isDemo
      ? ((typeof OFFICIAL_DEMO_RECORDS!=="undefined" && OFFICIAL_DEMO_RECORDS[n]) || null)
      : ((typeof OFFICIAL_LESSON_RECORDS!=="undefined" && OFFICIAL_LESSON_RECORDS[n]) || null));
    const p=this.profile();
    const custom=item.plan || {};
    const d = official ? JSON.parse(JSON.stringify(official)) : {
      no:n, topic:item.title||"", unit:item.unit||item.module||"", time:isDemo?`${item.hours||7} Hours (Practical Period)`:`${item.hours||1} Hours (Theory Period)`,
      proposed:item.plannedDate||"", conducted:item.doneDate||"", objectives:[], questions:[], steps:[], next:""
    };
    d.no=n;
    d.topic=item.title || d.topic || "";
    d.unit=d.unit || item.unit || item.module || "";
    d.proposed=d.proposed || item.plannedDate || "";
    d.conducted=item.doneDate || d.conducted || "";
    if(isDemo){
      if(custom.objective?.length) d.objectives=custom.objective;
      if(custom.tools?.length) d.tools=custom.tools;
      if(custom.questions?.length) d.questions=custom.questions;
      if(custom.nextDemo) d.next=custom.nextDemo;
      if(custom.steps?.length) d.steps=custom.steps;
      d.tools=d.tools||[]; if(item.hours)d.time=`${item.hours} Hours (Practical Period)`;
    }else{
      if(custom.objective?.length) d.objectives=custom.objective;
      if(custom.materials?.length) d.materials=custom.materials;
      if(custom.review) d.review=custom.review;
      if(custom.motivation) d.motivation=custom.motivation;
      if(custom.questions?.length) d.questions=custom.questions;
      if(custom.summary) d.summary=custom.summary;
      if(custom.assignment) d.assignment=custom.assignment;
      if(custom.nextLesson) d.next=custom.nextLesson;
      if(custom.steps?.length) d.steps=custom.steps;
      d.materials=d.materials||[]; if(item.hours)d.time=`${item.hours} Hours (Theory Period)`;
    }
    d.objectives=d.objectives||[]; d.questions=d.questions||[]; d.steps=d.steps||[];
    d.instructor=p.name; d.designation=p.designation; d.trade=p.trade; d.batch=p.batch; d.session=p.session; d.institute=p.institute;
    return d;
  },
  head(title,d) {
    return `<div class="doc-header">
      <div class="doc-gov">GOVERNMENT OF MAHARASHTRA</div>
      <div class="doc-dept">DIRECTORATE OF VOCATIONAL EDUCATION AND TRAINING (DVET), MAHARASHTRA</div>
      <div class="doc-iti">${this.esc(d.institute)}</div>
      <div class="doc-title">${title}</div>
    </div>`;
  },
  metaRows(type, d) {
    const label=type==="demo"?"Demonstration":"Lesson";
    const batchText=/Academic Session/i.test(d.batch||"") ? d.batch : `${d.batch}, Academic Session ${d.session}`;
    return `<table class="doc-meta">
      <tr><th>Name of Instructor</th><td>${this.esc(d.instructor)} (${this.esc(d.designation)})</td><th>Trade</th><td>${this.esc(d.trade)}</td></tr>
      <tr><th>Class / Batch</th><td>${this.esc(batchText)}</td><th>Unit No.</th><td>${this.esc(d.unit)}</td></tr>
      <tr><th>${label} No.</th><td>${this.esc(d.no)}</td><th>Time Allotted</th><td>${this.esc(d.time)}</td></tr>
      <tr><th>Proposed Date</th><td>${this.esc(d.proposed)}</td><th>Conducted Date</th><td>${this.esc(d.conducted)}</td></tr>
      <tr><th>${label} / Topic</th><td colspan="3">${this.esc(d.topic)}</td></tr>
    </table>`;
  },
  bullets(title, items) {
    const arr=(Array.isArray(items)?items:[items]).filter(Boolean);
    return `<div class="doc-section"><h4>${title}</h4>${arr.length?`<ol>${arr.map(x=>`<li>${this.esc(x)}</li>`).join("")}</ol>`:`<p>—</p>`}</div>`;
  },
  textSection(title, value){
    return `<div class="doc-section"><h4>${title}</h4><p>${this.esc(value||"—")}</p></div>`;
  },
  renderDemo(no) {
    const d=this.record("demo",no);
    const rows=d.steps.map(r=>`<tr><td>${this.esc(r[0])}</td><td>${this.esc(r[1])}</td><td>${this.esc(r[2])}</td></tr>`).join("") || `<tr><td colspan="3">No procedure rows are stored for this demonstration.</td></tr>`;
    return `<article class="print-doc">${this.head("DEMONSTRATION PLAN",d)}${this.metaRows("demo",d)}
      ${this.bullets("PURPOSE / OBJECTIVE:",d.objectives)}
      ${this.bullets("TOOLS, EQUIPMENT, SUPPLIES AND TRAINING AIDS REQUIRED:",d.tools)}
      <div class="doc-section"><table class="doc-table"><thead><tr><th>PROCEDURE IN SEQUENCE</th><th>KEY POINTS / SAFETY PRECAUTIONS</th><th>SPOT HINTS</th></tr></thead><tbody>${rows}</tbody></table></div>
      ${this.bullets("QUESTIONS:",d.questions)}
      ${this.textSection("NEXT DEMONSTRATION:",d.next)}
      ${this.signatures()}</article>`;
  },
  renderLesson(no) {
    const d=this.record("lesson",no);
    const rows=d.steps.map(r=>`<tr><td>${this.esc(r[0])}</td><td>${this.esc(r[1])}</td><td>${this.esc(r[2])}</td></tr>`).join("") || `<tr><td colspan="3">No teaching-step rows are stored for this lesson.</td></tr>`;
    return `<article class="print-doc">${this.head("LESSON PLAN",d)}${this.metaRows("lesson",d)}
      ${this.bullets("PURPOSE / OBJECTIVE:",d.objectives)}
      ${this.bullets("MATERIALS, EQUIPMENT AND TRAINING AIDS REQUIRED:",d.materials)}
      ${this.textSection("REVIEW:",d.review)}${this.textSection("MOTIVATION:",d.motivation)}
      <div class="doc-section"><table class="doc-table"><thead><tr><th>STEPS / TOPICS</th><th>INFORMATION POINTS</th><th>CHALK BOARD SUMMARY / SPOT HINTS</th></tr></thead><tbody>${rows}</tbody></table></div>
      ${this.bullets("QUESTIONS:",d.questions)}
      ${this.textSection("SUMMARY:",d.summary)}${this.textSection("ASSIGNMENT:",d.assignment)}${this.textSection("NEXT LESSON:",d.next)}
      ${this.signatures()}</article>`;
  },
  render(type,no){ return (type==="demo"||type==="practical") ? this.renderDemo(no) : this.renderLesson(no); },
  signatures() {
    return `<div class="doc-signatures"><div>INSTRUCTOR<br><span>(Signature & Date)</span></div><div>GROUP INSTRUCTOR<br><span>(Signature & Date)</span></div><div>VICE-PRINCIPAL / PRINCIPAL<br><span>(Signature & Date)</span></div></div>
      <div class="doc-footer-credit">Universal ITI Instructor Automation • Designed & Developed by Durgesh Kadam</div>`;
  },
  firstNo(type){ const list=(type==="demo"?DATA.practicals:DATA.theory)||[]; return list[0]?.no || 1; },
  preview(type,no) {
    const n=no||this.firstNo(type);
    PlanViewer.open(type==="demo"?"practical":"theory",Number(n));
  },
  print(type,no) {
    const n=no||this.firstNo(type);
    const body=this.render(type,n);
    const w=window.open("","_blank");
    if(!w){alert("Please allow pop-ups for printing. The full plan can still be viewed inside the app.");return;}
    w.document.open(); w.document.write(this.shell(body,true)); w.document.close();
  },
  shell(body, autoPrint) {
    return `<!doctype html><html><head><meta charset="utf-8"><title>ITI Plan</title>
      <style>${this.css(true)}</style></head><body>${body}${autoPrint?'<script>window.onload=function(){setTimeout(function(){window.print()},250)}<\/script>':''}</body></html>`;
  },
  css(printMode=false){ return `
      @page{size:A4;margin:10mm}*{box-sizing:border-box}body{font-family:Arial,Helvetica,sans-serif;color:#111;background:#fff;margin:0}
      .print-doc{width:100%;max-width:190mm;margin:0 auto;font-size:10.5px;line-height:1.35;background:#fff}
      .doc-header{text-align:center;border-bottom:2px solid #111;padding-bottom:7px;margin-bottom:8px}.doc-gov{font-weight:800;font-size:14px}.doc-dept{font-weight:700;font-size:11px;margin-top:2px}.doc-iti{font-weight:700;font-size:11px;margin-top:2px}.doc-title{font-size:17px;font-weight:900;margin-top:9px;text-decoration:underline}
      table{width:100%;border-collapse:collapse}.doc-meta th,.doc-meta td{border:1px solid #333;padding:5px;vertical-align:top}.doc-meta th{width:17%;background:#f1f1f1;text-align:left}.doc-meta td{width:33%}
      .doc-section{margin-top:9px;break-inside:auto}.doc-section h4{font-size:11px;margin:0 0 4px;font-weight:900}.doc-section p{margin:3px 0;white-space:normal}.doc-section ol{margin:3px 0 0 20px;padding:0}.doc-section li{margin:2px 0}
      .doc-table th,.doc-table td{border:1px solid #333;padding:5px;vertical-align:top}.doc-table th{background:#eee;text-align:center;font-weight:900}.doc-table tr{break-inside:avoid;page-break-inside:avoid}.doc-table thead{display:table-header-group}
      .doc-signatures{display:grid;grid-template-columns:1fr 1fr 1fr;gap:12px;margin-top:28px;break-inside:avoid;page-break-inside:avoid;text-align:center;font-weight:800}.doc-signatures div{padding-top:22px;border-top:1px solid #333}.doc-signatures span{font-weight:400;font-size:9px}.doc-footer-credit{text-align:center;margin-top:14px;font-size:8px;color:#555}
      @media print{body{overflow:visible!important}.print-doc{max-width:none}.doc-header,.doc-meta tr,.doc-section h4{break-after:avoid}.doc-section{overflow:visible!important}}
    `; }
};


