/* ===================== PHOTO GALLERY ===================== */
const Gallery = {
  openForm(){
    document.getElementById("galleryFile").value="";
    document.getElementById("galleryCaption").value="";
    document.getElementById("galleryModal").style.display="flex";
  },
  closeForm(){ document.getElementById("galleryModal").style.display="none"; },
  submitForm(){
    const file = document.getElementById("galleryFile").files[0];
    const caption = document.getElementById("galleryCaption").value.trim();
    if(!file){ alert("Choose a photo."); return; }
    const img = new Image();
    const reader = new FileReader();
    reader.onload = ()=>{
      img.onload = ()=>{
        const maxW = 500;
        const scale = Math.min(1, maxW/img.width);
        const canvas = document.createElement("canvas");
        canvas.width = img.width*scale;
        canvas.height = img.height*scale;
        canvas.getContext("2d").drawImage(img,0,0,canvas.width,canvas.height);
        const dataUrl = canvas.toDataURL("image/jpeg", 0.6);
        DATA.gallery.unshift({id:uid(), date:todayISO(), caption, dataUrl});
        try{ saveData(); }catch(e){ alert("Storage is full. Remove some old photos first, or export a backup and clear the gallery."); DATA.gallery.shift(); return; }
        Gallery.closeForm(); Gallery.render();
      };
      img.src = reader.result;
    };
    reader.readAsDataURL(file);
  },
  remove(id){
    if(!confirm("Delete this photo?")) return;
    DATA.gallery = DATA.gallery.filter(g=>g.id!==id);
    saveData(); Gallery.render();
  },
  render(){
    document.getElementById("galleryGrid").innerHTML = DATA.gallery.map(g=>`
      <div class="gallery-item">
        <img src="${g.dataUrl}" alt="${g.caption}">
        <div class="gallery-caption">
          <b>${g.caption||"(no caption)"}</b>
          <span class="date">${g.date}</span>
          ${SESSION.role==="instructor"? `<button class="btn ghost small" onclick="Gallery.remove('${g.id}')" style="margin-top:6px">Delete</button>`:""}
        </div>
      </div>`).join("") || `<p class="muted">No photos added yet.</p>`;
  }
};

