/* ===================== LEAVE & DISCIPLINE ===================== */
const Leave = {
  populateSelects(){
    document.getElementById("undertakingTrainee").innerHTML = DATA.trainees.map(t=>`<option value="${t.id}">${t.roll} — ${t.name}</option>`).join("");
  },
  apply(){
    const type = document.getElementById("leaveType").value;
    const fromDate = document.getElementById("leaveFrom").value;
    const toDate = document.getElementById("leaveTo").value;
    const reason = document.getElementById("leaveReason").value.trim();
    const certNote = document.getElementById("leaveCert").value.trim();
    if(!fromDate || !toDate){ alert("Select From and To dates."); return; }
    if(!reason){ alert("Enter a reason."); return; }
    DATA.leaves.unshift({id:uid(), traineeId:SESSION.traineeId, type, fromDate, toDate, reason, certNote, status:"pending", appliedDate:todayISO()});
    saveData();
    document.getElementById("leaveReason").value=""; document.getElementById("leaveCert").value="";
    Leave.render();
    alert("Leave application submitted. Your instructor will review it.");
  },
  approve(id){
    const lv = DATA.leaves.find(x=>x.id===id);
    if(!lv) return;
    lv.status="approved";
    // mark attendance L for each date in range
    const range = safeDateRangeLoop(lv.fromDate, lv.toDate, 3660);
    if(!range.valid){ alert("Invalid leave date range."); return; }
    let d = range.start, end = range.end, guard=0;
    while(d<=end && guard++<range.maxDays){
      const iso = d.toISOString().slice(0,10);
      if(!DATA.attendance[iso]) DATA.attendance[iso]={};
      DATA.attendance[iso][lv.traineeId]="L";
      d.setDate(d.getDate()+1);
    }
    saveData(); Leave.render(); Trainees.render(); Dashboard.render();
  },
  reject(id){
    const lv = DATA.leaves.find(x=>x.id===id);
    if(!lv) return;
    lv.status="rejected";
    saveData(); Leave.render();
  },
  render(){
    const isStudent = SESSION.role==="student";
    const rows = isStudent ? DATA.leaves.filter(l=>l.traineeId===SESSION.traineeId) : DATA.leaves;
    document.getElementById("leaveTableBody").innerHTML = rows.map(l=>{
      const t = DATA.trainees.find(x=>x.id===l.traineeId);
      const badge = l.status==="approved"? `<span class="badge signed">Approved</span>`
        : l.status==="rejected"? `<span class="badge pending" style="background:#fde3dc;color:var(--bad)">Rejected</span>`
        : `<span class="badge pending">Pending</span>`;
      const actions = (!isStudent && l.status==="pending")
        ? `<button class="btn ghost small" onclick="Leave.approve('${l.id}')">Approve</button> <button class="btn ghost small" onclick="Leave.reject('${l.id}')">Reject</button>`
        : "";
      return `<tr><td>${t? t.roll+' — '+t.name : '—'}</td><td>${l.type}</td><td>${l.fromDate}</td><td>${l.toDate}</td><td>${l.reason}${l.certNote? ' <br><a href="'+l.certNote+'" target="_blank">Certificate</a>':''}</td><td>${badge}</td><td>${actions}</td></tr>`;
    }).join("") || `<tr><td colspan="7" class="muted">No leave applications yet.</td></tr>`;

    Leave.renderWarnings();
    Leave.renderUndertakings();
  },
  saveThreshold(){
    const val = Number(document.getElementById("attThresholdInput").value);
    if(!val || val<1 || val>100){ alert("Enter a valid percentage."); return; }
    DATA.meta.attendanceThreshold = val;
    saveData(); Leave.renderWarnings();
  },
  renderWarnings(){
    const input = document.getElementById("attThresholdInput");
    if(input) input.value = DATA.meta.attendanceThreshold;
    const threshold = DATA.meta.attendanceThreshold;
    const below = DATA.trainees.filter(t=>{
      const pct = Trainees.attendancePct(t.id);
      return pct!=="—" && parseInt(pct) < threshold;
    });
    const tbody = document.getElementById("belowThresholdTableBody");
    if(tbody) tbody.innerHTML = below.map(t=>`
      <tr><td>${t.roll} — ${t.name}</td><td class="bad" style="color:var(--bad);font-weight:700">${Trainees.attendancePct(t.id)}</td>
      <td>${t.guardianName||'—'} ${t.guardianPhone? '('+t.guardianPhone+')':''}</td>
      <td>${SESSION.role==="instructor"? `<button class="btn ghost small" onclick="Leave.generateWarning('${t.id}')">Generate Takit Patra</button>`:""}</td></tr>
    `).join("") || `<tr><td colspan="4" class="muted">No trainees currently below ${threshold}%.</td></tr>`;

    const wtbody = document.getElementById("warningsTableBody");
    if(wtbody) wtbody.innerHTML = DATA.warnings.map(w=>{
      const t = DATA.trainees.find(x=>x.id===w.traineeId);
      return `<tr><td>${t? t.roll+' — '+t.name:'—'}</td><td>${w.date}</td><td>${w.attendancePct}%</td>
        <td>${w.status==="acknowledged"? `<span class="badge signed">Acknowledged ${w.ackDate||''}</span>`:`<span class="badge pending">Issued</span>`}</td>
        <td>${w.status!=="acknowledged" && SESSION.role==="instructor" ? `<button class="btn ghost small" onclick="Leave.ackWarning('${w.id}')">Mark Acknowledged</button>`:""}</td></tr>`;
    }).join("") || `<tr><td colspan="5" class="muted">No warnings issued yet.</td></tr>`;
  },
  generateWarning(traineeId){
    const t = DATA.trainees.find(x=>x.id===traineeId);
    const pct = parseInt(Trainees.attendancePct(traineeId));
    DATA.warnings.unshift({id:uid(), traineeId, date:todayISO(), attendancePct:pct, status:"issued"});
    saveData(); Leave.renderWarnings();
    Reports.printTakitPatra(t, pct);
  },
  ackWarning(id){
    const w = DATA.warnings.find(x=>x.id===id);
    if(!w) return;
    w.status="acknowledged"; w.ackDate=todayISO();
    saveData(); Leave.renderWarnings();
  },
  addUndertaking(){
    const traineeId = document.getElementById("undertakingTrainee").value;
    const note = document.getElementById("undertakingNote").value.trim();
    if(!traineeId){ alert("Select a trainee."); return; }
    if(!note){ alert("Enter a reason/context."); return; }
    DATA.undertakings.unshift({id:uid(), traineeId, date:todayISO(), note, status:"pending"});
    saveData();
    document.getElementById("undertakingNote").value="";
    Leave.renderUndertakings();
  },
  markUndertakingFiled(id){
    const u = DATA.undertakings.find(x=>x.id===id);
    if(!u) return;
    const t = DATA.trainees.find(x=>x.id===u.traineeId);
    Reports.printUndertaking(u, t);
    u.status="filed"; u.filedDate=todayISO();
    saveData(); Leave.renderUndertakings();
  },
  renderUndertakings(){
    const tbody = document.getElementById("undertakingsTableBody");
    if(!tbody) return;
    tbody.innerHTML = DATA.undertakings.map(u=>{
      const t = DATA.trainees.find(x=>x.id===u.traineeId);
      return `<tr><td>${t? t.roll+' — '+t.name:'—'}</td><td>${u.date}</td><td>${u.note}</td>
        <td>${u.status==="filed"? `<span class="badge signed">Filed ${u.filedDate||''}</span>`:`<span class="badge pending">Pending</span>`}</td>
        <td>${u.status!=="filed" && SESSION.role==="instructor" ? `<button class="btn ghost small" onclick="Leave.markUndertakingFiled('${u.id}')">Print &amp; Mark Filed</button>`:""}</td></tr>`;
    }).join("") || `<tr><td colspan="5" class="muted">No undertakings logged yet.</td></tr>`;
  }
};


/* ===================== PLAN & MATERIALS VIEWER ===================== */
const PLAN_FIELDS = {
  practical: [["objective","Purpose / Objective",true],["tools","Tools, Equipment & Training Aids",true],["questions","Questions",true],["nextDemo","Next Demonstration",false]],
  theory: [["objective","Purpose / Objective",true],["materials","Materials, Equipment & Training Aids",true],["review","Review",false],["motivation","Motivation",false],["questions","Questions",true],["summary","Summary",false],["assignment","Assignment",false],["nextLesson","Next Lesson",false]]
};

const PlanViewer = {
  current:{type:null, no:null},
  open(type, no){
    this.current={type,no:Number(no)};
    const list=type==="practical" ? DATA.practicals : DATA.theory;
    const item=list.find(x=>Number(x.no)===Number(no));
    if(!item) return;
    const isStudent=SESSION.role==="student";
    document.getElementById("planModalTitle").textContent = isStudent ? `${type==="practical"?"Practical":"Theory"} ${no}: ${item.title}` : `${type==="practical"?"Demonstration":"Lesson"} Plan No. ${no}`;

    const m=item.materials || {pdfLink:"",youtubeLink:"",updatedDate:null};
    let materialsHtml="";
    if(isStudent){
      materialsHtml=`<div class="plan-materials"><h4>📎 Teaching Materials</h4>
        ${m.pdfLink?`<p>📄 <a href="${m.pdfLink}" target="_blank" rel="noopener">Open Notes PDF</a></p>`:""}
        ${m.youtubeLink?`<p>▶️ <a href="${m.youtubeLink}" target="_blank" rel="noopener">Watch on YouTube</a></p>`:""}
        ${(!m.pdfLink&&!m.youtubeLink)?`<p class="muted">Not uploaded by your instructor yet.</p>`:""}</div>`;
    }else{
      const fullDoc=RecordFormats.render(type==="practical"?"demo":"lesson",Number(no));
      const pm=item.planMeta||{};
      const statusHtml=pm.status?`<div class="callout" style="margin-bottom:10px"><b>Plan status:</b> ${RecordFormats.esc(String(pm.status).replace(/-/g,' ').toUpperCase())}${pm.approvedBy?` · Approved by ${RecordFormats.esc(pm.approvedBy)}`:''}${pm.version?` · Version ${pm.version}`:''}</div>`:'';
      materialsHtml=`${statusHtml}
        <div class="plan-preview-toolbar">
          <button class="btn secondary small" onclick="RecordFormats.print('${type==="practical"?"demo":"lesson"}',${Number(no)})">🖨️ Print / Save PDF</button>
          ${SESSION.role==="instructor"?`<button class="btn primary small" onclick="InstructorAI.openPlanDraft('${type}',${Number(no)})">✨ AI Draft Plan</button><button class="btn ghost small" onclick="PlanViewer.editPlan()">✏️ Edit Text Sections</button>`:""}
        </div>
        <div class="plan-document-wrap"><style>${RecordFormats.css(false)}</style>${fullDoc}</div>
        ${SESSION.role==="instructor"?`<div class="plan-materials"><h4>📎 Teaching Materials (for students)</h4>
          <div class="field"><label>Notes PDF link</label><input type="text" id="planPdfLink" value="${m.pdfLink||''}" placeholder="Paste Drive/other link to your notes PDF"></div>
          <div class="field"><label>YouTube video link</label><input type="text" id="planYoutubeLink" value="${m.youtubeLink||''}" placeholder="https://youtube.com/watch?v=..."></div>
          <button class="btn primary small" onclick="PlanViewer.saveMaterials()">Save Materials</button>${m.updatedDate?`<p class="muted">Last updated ${m.updatedDate}</p>`:""}</div>`:""}`;
    }
    document.getElementById("planModalBody").innerHTML=materialsHtml;
    document.getElementById("planModal").style.display="flex";
    const card=document.querySelector("#planModal .modal-card"); if(card){card.scrollTop=0;}
  },
  editPlan(){
    const {type,no}=this.current;
    const list=type==="practical"?DATA.practicals:DATA.theory;
    const item=list.find(x=>Number(x.no)===Number(no)); if(!item)return;
    const official=RecordFormats.record(type==="practical"?"demo":"lesson",no);
    const existing=item.plan||{};
    const seed=type==="practical"?{
      objective:official.objectives||[], tools:official.tools||[], questions:official.questions||[], nextDemo:official.next||""
    }:{
      objective:official.objectives||[], materials:official.materials||[], review:official.review||"", motivation:official.motivation||"", questions:official.questions||[], summary:official.summary||"", assignment:official.assignment||"", nextLesson:official.next||""
    };
    const fields=PLAN_FIELDS[type];
    const formHtml=fields.map(([key,label,isArray])=>{
      const val=(key in existing)?existing[key]:seed[key];
      const textVal=isArray?(val||[]).join("\n"):(val||"");
      return `<div class="field"><label>${label}${isArray?' <span class="muted">(one per line)</span>':''}</label><textarea id="planField_${key}" rows="${isArray?4:3}">${RecordFormats.esc(textVal)}</textarea></div>`;
    }).join("");
    document.getElementById("planModalBody").innerHTML=`<p class="muted">Edit the text sections below. The official procedure/teaching table, plan header, dates and signature area remain part of the full document.</p>${formHtml}<div class="field-row" style="justify-content:flex-end"><button class="btn ghost" onclick="PlanViewer.open('${type}',${no})">Cancel</button><button class="btn primary" onclick="PlanViewer.savePlan()">Save & View Full Plan</button></div>`;
  },
  savePlan(){
    const {type,no}=this.current; const list=type==="practical"?DATA.practicals:DATA.theory; const item=list.find(x=>Number(x.no)===Number(no)); if(!item)return;
    const newPlan={}; PLAN_FIELDS[type].forEach(([key,label,isArray])=>{const raw=document.getElementById("planField_"+key).value; newPlan[key]=isArray?raw.split("\n").map(s=>s.trim()).filter(Boolean):raw.trim();});
    item.plan={...(item.plan||{}),...newPlan};
    item.planMeta={...(item.planMeta||{}),status:"instructor-edited",editedAt:new Date().toISOString(),editedBy:SESSION?.name||"Instructor",version:Number(item.planMeta?.version||0)+1};
    saveData(); alert("Plan saved. Review it before final use."); this.open(type,no);
  },
  close(){document.getElementById("planModal").style.display="none";},
  saveMaterials(){
    const {type,no}=this.current; const list=type==="practical"?DATA.practicals:DATA.theory; const item=list.find(x=>Number(x.no)===Number(no)); if(!item)return;
    item.materials={pdfLink:document.getElementById("planPdfLink").value.trim(),youtubeLink:document.getElementById("planYoutubeLink").value.trim(),updatedDate:todayISO()}; saveData(); alert("Materials saved."); this.open(type,no);
  }
};


/* ===================== CLASS TEST (MCQ EXAMS) ===================== */
const Exam = {
  currentExamId:null,
  currentAttempt:{},

  openCreate(){
    document.getElementById("examTitle").value="";
    document.getElementById("examDate").value=todayISO();
    document.getElementById("examCreateModal").style.display="flex";
  },
  closeCreate(){ document.getElementById("examCreateModal").style.display="none"; },
  submitCreate(){
    const title = document.getElementById("examTitle").value.trim();
    const date = document.getElementById("examDate").value;
    if(!title){ alert("Enter a title."); return; }
    const exam = {id:uid(), title, date, status:"draft", questions:[]};
    DATA.exams.unshift(exam);
    saveData(); Exam.closeCreate(); Exam.render();
  },
  deleteExam(id){
    if(!confirm("Delete this exam and all its questions? Attempts already submitted stay on record.")) return;
    DATA.exams = DATA.exams.filter(e=>e.id!==id);
    saveData();
    if(Exam.currentExamId===id) Exam.closeBuilder();
    Exam.render();
  },

  manage(id){
    Exam.currentExamId = id;
    const exam = DATA.exams.find(e=>e.id===id);
    if(!exam) return;
    document.getElementById("examBuilder").style.display="block";
    document.getElementById("examBuilderTitle").textContent = `Exam Builder — ${exam.title} (${exam.date})`;
    document.getElementById("examPublishBtn").textContent = exam.status==="published" ? "Unpublish" : "Publish";
    document.getElementById("examResultsBox").innerHTML="";
    Exam.renderQuestions();
  },
  closeBuilder(){
    Exam.currentExamId=null;
    document.getElementById("examBuilder").style.display="none";
  },
  renderQuestions(){
    const exam = DATA.exams.find(e=>e.id===Exam.currentExamId);
    if(!exam) return;
    document.getElementById("examQuestionsTableBody").innerHTML = exam.questions.map((q,i)=>`
      <tr><td>${i+1}</td><td>${q.text}</td><td>${["A","B","C","D"][q.correctIndex]}. ${q.options[q.correctIndex]}</td><td>${q.marks}</td>
      <td><button class="btn ghost small" onclick="Exam.deleteQuestion('${q.id}')">Delete</button></td></tr>
    `).join("") || `<tr><td colspan="5" class="muted">No questions yet.</td></tr>`;
  },
  deleteQuestion(qId){
    const exam = DATA.exams.find(e=>e.id===Exam.currentExamId);
    if(!exam) return;
    exam.questions = exam.questions.filter(q=>q.id!==qId);
    saveData(); Exam.renderQuestions(); Exam.render();
  },
  openAddQuestion(){
    document.getElementById("qText").value="";
    document.getElementById("qOptA").value="";
    document.getElementById("qOptB").value="";
    document.getElementById("qOptC").value="";
    document.getElementById("qOptD").value="";
    document.getElementById("qCorrect").value="0";
    document.getElementById("qMarks").value="1";
    document.getElementById("examQuestionModal").style.display="flex";
  },
  closeAddQuestion(){ document.getElementById("examQuestionModal").style.display="none"; },
  submitAddQuestion(){
    const exam = DATA.exams.find(e=>e.id===Exam.currentExamId);
    if(!exam) return;
    const text = document.getElementById("qText").value.trim();
    const options = [document.getElementById("qOptA").value.trim(), document.getElementById("qOptB").value.trim(),
                      document.getElementById("qOptC").value.trim(), document.getElementById("qOptD").value.trim()];
    if(!text || options.some(o=>!o)){ alert("Fill in the question and all four options."); return; }
    const correctIndex = Number(document.getElementById("qCorrect").value);
    const marks = Number(document.getElementById("qMarks").value)||1;
    exam.questions.push({id:uid(), text, options, correctIndex, marks});
    saveData(); Exam.closeAddQuestion(); Exam.renderQuestions(); Exam.render();
  },
  togglePublish(){
    const exam = DATA.exams.find(e=>e.id===Exam.currentExamId);
    if(!exam) return;
    if(exam.status!=="published" && exam.questions.length===0){ alert("Add at least one question before publishing."); return; }
    exam.status = exam.status==="published" ? "draft" : "published";
    saveData();
    document.getElementById("examPublishBtn").textContent = exam.status==="published" ? "Unpublish" : "Publish";
    Exam.render();
  },
  viewResults(){
    const exam = DATA.exams.find(e=>e.id===Exam.currentExamId);
    if(!exam) return;
    const maxScore = exam.questions.reduce((s,q)=>s+q.marks,0);
    const rows = Reports.sortedTrainees().map(t=>{
      const attempt = DATA.examAttempts.find(a=>a.examId===exam.id && a.traineeId===t.id);
      return `<tr><td>${t.roll} — ${t.name}</td>
        <td>${attempt? attempt.score+' / '+maxScore : '<span class="muted">Not attempted</span>'}</td>
        <td>${attempt? Math.round(attempt.score/maxScore*100)+'%' : '—'}</td>
        <td>${attempt? attempt.submittedAt : '—'}</td></tr>`;
    }).join("");
    document.getElementById("examResultsBox").innerHTML = `
      <h4 style="margin-top:16px">Results — ${exam.title}</h4>
      <table class="datatable"><thead><tr><th>Trainee</th><th>Score</th><th>%</th><th>Submitted</th></tr></thead><tbody>${rows}</tbody></table>
    `;
  },

  render(){
    if(SESSION.role==="instructor"){
      document.getElementById("examListTableBody").innerHTML = DATA.exams.map(e=>`
        <tr><td>${e.title}</td><td>${e.date}</td><td>${e.questions.length}</td>
        <td>${e.status==="published"? `<span class="badge signed">Published</span>`:`<span class="badge pending">Draft</span>`}</td>
        <td><button class="btn ghost small" onclick="Exam.manage('${e.id}')">Manage</button>
        <button class="btn ghost small" onclick="Exam.deleteExam('${e.id}')">Delete</button></td></tr>
      `).join("") || `<tr><td colspan="5" class="muted">No exams created yet.</td></tr>`;
    }
    if(SESSION.role==="student"){
      const published = DATA.exams.filter(e=>e.status==="published");
      document.getElementById("examAvailableTableBody").innerHTML = published.map(e=>{
        const attempted = DATA.examAttempts.some(a=>a.examId===e.id && a.traineeId===SESSION.traineeId);
        return `<tr><td>${e.title}</td><td>${e.date}</td><td>${e.questions.length}</td>
          <td>${attempted? `<span class="badge signed">Completed</span>` : `<button class="btn primary small" onclick="Exam.start('${e.id}')">Start Test</button>`}</td></tr>`;
      }).join("") || `<tr><td colspan="4" class="muted">No tests available right now.</td></tr>`;

      const myAttempts = DATA.examAttempts.filter(a=>a.traineeId===SESSION.traineeId);
      document.getElementById("examMyResultsTableBody").innerHTML = myAttempts.map(a=>{
        const e = DATA.exams.find(x=>x.id===a.examId);
        return `<tr><td>${e? e.title:'—'}</td><td>${a.score} / ${a.maxScore}</td><td>${Math.round(a.score/a.maxScore*100)}%</td><td>${a.submittedAt}</td></tr>`;
      }).join("") || `<tr><td colspan="4" class="muted">No tests completed yet.</td></tr>`;
    }
  },

  start(examId){
    const exam = DATA.exams.find(e=>e.id===examId);
    if(!exam) return;
    Exam.currentExamId = examId;
    Exam.currentAttempt = {};
    document.getElementById("examTakeTitle").textContent = exam.title;
    document.getElementById("examTakeBody").innerHTML = exam.questions.map((q,i)=>`
      <div style="margin-bottom:16px;padding-bottom:12px;border-bottom:1px solid var(--border)">
        <p style="font-weight:600;margin-bottom:8px">${i+1}. ${q.text} <span class="muted">(${q.marks} mark${q.marks>1?'s':''})</span></p>
        ${q.options.map((opt,idx)=>`
          <label style="display:block;margin-bottom:6px;cursor:pointer">
            <input type="radio" name="q_${q.id}" value="${idx}" onchange="Exam.setAnswer('${q.id}',${idx})"> ${["A","B","C","D"][idx]}. ${opt}
          </label>`).join("")}
      </div>
    `).join("");
    document.getElementById("examTakeModal").style.display="flex";
  },
  setAnswer(qId, idx){ Exam.currentAttempt[qId] = idx; },
  closeTake(){ document.getElementById("examTakeModal").style.display="none"; },
  submitAttempt(){
    const exam = DATA.exams.find(e=>e.id===Exam.currentExamId);
    if(!exam) return;
    const unanswered = exam.questions.filter(q=>!(q.id in Exam.currentAttempt));
    if(unanswered.length && !confirm(`${unanswered.length} question(s) unanswered. Submit anyway?`)) return;
    let score = 0;
    const maxScore = exam.questions.reduce((s,q)=>s+q.marks,0);
    exam.questions.forEach(q=>{
      if(Exam.currentAttempt[q.id]===q.correctIndex) score += q.marks;
    });
    DATA.examAttempts.push({id:uid(), examId:exam.id, traineeId:SESSION.traineeId, answers:{...Exam.currentAttempt}, score, maxScore, submittedAt:todayISO()});
    saveData();
    Exam.closeTake();
    alert(`Test submitted! Your score: ${score} / ${maxScore}`);
    Exam.render();
  }
};


