const Visits = {
  currentVisitId:null,
  openCreate(){
    document.getElementById("visitType").value="OJT";
    document.getElementById("visitTitle").value="";
    document.getElementById("visitOrg").value="";
    document.getElementById("visitDate").value=todayISO();
    document.getElementById("visitPurpose").value="";
    document.getElementById("visitCreateModal").style.display="flex";
  },
  closeCreate(){ document.getElementById("visitCreateModal").style.display="none"; },
  submitCreate(){
    const type = document.getElementById("visitType").value;
    const title = document.getElementById("visitTitle").value.trim();
    const organization = document.getElementById("visitOrg").value.trim();
    const date = document.getElementById("visitDate").value;
    const purpose = document.getElementById("visitPurpose").value.trim();
    if(!title || !organization || !date){ alert("Fill in title, organization, and date."); return; }
    DATA.visits.unshift({id:uid(), type, title, organization, date, purpose, attendees:[]});
    saveData(); Visits.closeCreate(); Visits.render();
  },
  remove(id){
    if(!confirm("Delete this record?")) return;
    DATA.visits = DATA.visits.filter(v=>v.id!==id);
    saveData(); Visits.render();
  },
  openAttendance(id){
    Visits.currentVisitId = id;
    const visit = DATA.visits.find(v=>v.id===id);
    if(!visit) return;
    document.getElementById("visitAttendanceList").innerHTML = DATA.trainees.map(t=>`
      <label style="display:block;margin-bottom:8px">
        <input type="checkbox" value="${t.id}" ${visit.attendees.includes(t.id)?'checked':''}> ${t.roll} — ${t.name}
      </label>`).join("") || `<p class="muted">No trainees added yet.</p>`;
    document.getElementById("visitAttendanceModal").style.display="flex";
  },
  closeAttendance(){ document.getElementById("visitAttendanceModal").style.display="none"; },
  saveAttendance(){
    const visit = DATA.visits.find(v=>v.id===Visits.currentVisitId);
    if(!visit) return;
    const checked = [...document.querySelectorAll("#visitAttendanceList input:checked")].map(el=>el.value);
    visit.attendees = checked;
    saveData(); Visits.closeAttendance(); Visits.render();
  },
  render(){
    const isStudent = SESSION.role==="student";
    document.getElementById("visitsTableBody").innerHTML = DATA.visits.map(v=>{
      if(isStudent && !v.attendees.includes(SESSION.traineeId)) return "";
      const actions = SESSION.role==="instructor" ? `
        <button class="btn ghost small" onclick="Visits.openAttendance('${v.id}')">Attendance</button>
        <button class="btn ghost small" onclick="Reports.printVisitLetter('${v.id}')">Letter</button>
        <button class="btn ghost small" onclick="Reports.printVisitConsent('${v.id}')">Consent Letters</button>
        <button class="btn ghost small" onclick="Reports.printVisitAttendance('${v.id}')">Attendance Sheet</button>
        <button class="btn ghost small" onclick="Reports.printVisitCertificates('${v.id}')">Certificates</button>
        <button class="btn ghost small" onclick="Visits.remove('${v.id}')">Delete</button>` : "";
      return `<tr><td>${v.date}</td><td>${v.type}</td><td>${v.title}</td><td>${v.organization}</td><td>${v.attendees.length}</td><td>${actions}</td></tr>`;
    }).join("") || `<tr><td colspan="6" class="muted">No OJT/visit records yet.</td></tr>`;
  }
};


