let _chartSyllabus=null, _chartAttendance=null;

/* ===================== DASHBOARD ===================== */
const Dashboard = {
  render(){
    const isPrincipal = SESSION?.role === "principal";
    const principalPanel = document.getElementById("principalDashboard");
    if(principalPanel) principalPanel.style.display = isPrincipal ? "block" : "none";
    if(isPrincipal){
      const instructors=(DATA.users||[]).filter(u=>u.role==="instructor");
      const active=instructors.filter(u=>u.active!==false).length;
      const disabled=instructors.length-active;
      const pEl=document.getElementById("principalStats");
      if(pEl) pEl.innerHTML = `
        <div class="principal-stat"><span>👥</span><div><b>${instructors.length}</b><small>Instructors</small></div></div>
        <div class="principal-stat good"><span>✓</span><div><b>${active}</b><small>Active accounts</small></div></div>
        <div class="principal-stat ${disabled?'warn':''}"><span>⏸</span><div><b>${disabled}</b><small>Disabled accounts</small></div></div>
        <div class="principal-stat"><span>📚</span><div><b>${DATA.modules.length}</b><small>Modules configured</small></div></div>`;
      const list=document.getElementById("principalInstructorList");
      if(list) list.innerHTML = instructors.length ? instructors.map(u=>`<div class="instructor-row"><div class="avatar">${esc((u.name||"I").charAt(0).toUpperCase())}</div><div class="instructor-main"><b>${esc(u.name)}</b><span>@${esc(u.username)}</span></div><span class="account-state ${u.active===false?'off':'on'}">${u.active===false?'Disabled':'Active'}</span></div>`).join("") : '<div class="empty-state">No instructor accounts created yet. Click <b>Instructor Accounts</b> to create the first one.</div>';
      // Principal should not see the instructor's operational dashboard widgets.
      ["dashCards","chartSyllabus","chartAttendance","dashLatestNotice","dashRoadmap","pendingSigList","syllabusBarWrap"].forEach(id=>{ const el=document.getElementById(id); if(el) { const holder=el.closest('.card')||el; holder.style.display='none'; }});
      document.getElementById("heroGreeting").textContent = "Principal Dashboard";
      document.getElementById("heroSub").textContent = `${DATA.meta.institute} · ${instructors.length} instructor account${instructors.length===1?'':'s'}`;
      return;
    }
    ["dashCards","chartSyllabus","chartAttendance","dashLatestNotice","dashRoadmap","pendingSigList","syllabusBarWrap"].forEach(id=>{ const el=document.getElementById(id); if(el) { const holder=el.closest('.card')||el; holder.style.display=''; }});
    const total = DATA.trainees.length;
    const todayAtt = DATA.attendance[todayISO()] || null;
    const presentToday = todayAtt ? Object.values(todayAtt).filter(s=>s==="P").length : null;

    const donePrac = DATA.practicals.filter(p=>p.status==="completed").length;
    const totalPrac = DATA.practicals.length;
    const doneTheory = DATA.theory.filter(t=>t.status==="completed").length;
    const totalTheory = DATA.theory.length;
    const combinedDone = donePrac + doneTheory;
    const combinedTotal = totalPrac + (totalTheory||0);
    const pct = combinedTotal? Math.round((combinedDone/combinedTotal)*100) : 0;

    document.getElementById("dashCards").innerHTML = `
      <div class="card"><div class="stat-card">
        <div class="stat-icon" style="background:linear-gradient(135deg,var(--navy),#1d5686);color:#fff">👥</div>
        <div><div class="stat-label">Trainees</div><div class="stat">${total}</div></div>
      </div></div>
      <div class="card accent-teal"><div class="stat-card">
        <div class="stat-icon" style="background:linear-gradient(135deg,var(--teal),#14a89b);color:#fff">✅</div>
        <div><div class="stat-label">Today's Attendance</div>
        <div class="stat ${todayAtt? '':'warn'}">${todayAtt? presentToday+' / '+total : 'Not marked'}</div></div>
      </div></div>
      <div class="card accent-brass"><div class="stat-card">
        <div class="stat-icon" style="background:linear-gradient(135deg,var(--brass),#c9922f);color:#fff">🖥️</div>
        <div><div class="stat-label">Practicals Completed</div>
        <div class="stat">${donePrac} / ${totalPrac}</div></div>
      </div></div>
      <div class="card accent-plum"><div class="stat-card">
        <div class="stat-icon" style="background:linear-gradient(135deg,var(--plum),#a34a90);color:#fff">📘</div>
        <div><div class="stat-label">Theory Completed</div>
        <div class="stat ${totalTheory? '':'warn'}">${totalTheory? doneTheory+' / '+totalTheory : 'Not added yet'}</div></div>
      </div></div>
      <div class="card accent-coral"><div class="stat-card">
        <div class="stat-icon" style="background:linear-gradient(135deg,var(--coral),#d97847);color:#fff">📊</div>
        <div><div class="stat-label">Overall Syllabus</div>
        <div class="stat ${pct<50?'bad':pct<80?'warn':''}">${pct}%</div></div>
      </div></div>
    `;

    Dashboard.renderCharts(donePrac, totalPrac, doneTheory, totalTheory);

    const latest = DATA.notices[0];
    document.getElementById("dashLatestNotice").innerHTML = latest
      ? `<div class="notice"><span class="date">${latest.date}</span><h4>${latest.title}</h4><p>${latest.body||""}</p></div>`
      : `<p class="muted">No notices posted yet.</p>`;

    const nextPracs = DATA.practicals.filter(p=>p.status!=="completed").slice(0,3);
    const nextTheory = DATA.theory.filter(t=>t.status!=="completed").slice(0,3);
    const dateTag = d => d? ` <span class="muted">(planned ${d})</span>` : ` <span class="muted">(no planned date set)</span>`;
    document.getElementById("dashRoadmap").innerHTML = `
      <p class="stat-label" style="margin-bottom:4px">Next Practicals</p>
      <ul style="margin:0 0 12px;padding-left:18px;font-size:.9em">
        ${nextPracs.map(p=>`<li>Demo ${p.no}: ${p.title}${dateTag(p.plannedDate)}</li>`).join("") || '<li class="muted">All practicals complete!</li>'}
      </ul>
      <p class="stat-label" style="margin-bottom:4px">Next Theory Topics</p>
      <ul style="margin:0;padding-left:18px;font-size:.9em">
        ${nextTheory.map(t=>`<li>Lesson ${t.no}: ${t.title}${dateTag(t.plannedDate)}</li>`).join("") || '<li class="muted">All theory complete!</li>'}
      </ul>
    `;

    const pending = Object.entries(DATA.signatures).filter(([k,v])=>v.status==="pending");
    document.getElementById("pendingSigList").innerHTML = pending.length
      ? pending.map(([k,v])=>`<div class="pending-item"><span>${k}</span><span class="badge pending">Awaiting signature</span></div>`).join("")
      : `<p class="muted">Nothing pending. Registers you generate from Reports will appear here until marked signed.</p>`;

    const bar = document.createElement("div");
    const nextPrac = DATA.practicals.find(p=>p.status!=="completed");
    bar.innerHTML = `<div style="background:#e2e6ea;border-radius:8px;height:22px;overflow:hidden">
      <div style="background:var(--brass);height:100%;width:${pct}%"></div></div>
      <p class="muted" style="margin-top:6px">${combinedDone} of ${combinedTotal||'0'} items (practical + theory) marked complete.
      ${nextPrac? 'Next practical: Demo '+nextPrac.no : ''}</p>`;
    document.getElementById("syllabusBarWrap").innerHTML="";
    document.getElementById("syllabusBarWrap").appendChild(bar);
  },
  renderCharts(donePrac, totalPrac, doneTheory, totalTheory){
    if(typeof Chart === "undefined") return; // offline fallback: charts just skipped
    const c1 = document.getElementById("chartSyllabus");
    const c2 = document.getElementById("chartAttendance");
    if(_chartSyllabus) _chartSyllabus.destroy();
    if(_chartAttendance) _chartAttendance.destroy();

    _chartSyllabus = new Chart(c1, {
      type:"doughnut",
      data:{
        labels:["Practical done","Practical pending","Theory done","Theory pending"],
        datasets:[{
          data:[donePrac, totalPrac-donePrac, doneTheory, (totalTheory-doneTheory)||0],
          backgroundColor:["#123a5e","#c9d3db","#a9761d","#ecdcb8"]
        }]
      },
      options:{plugins:{legend:{position:"bottom", labels:{boxWidth:12,font:{size:10}}}}}
    });

    const days = Array.from({length:7},(_,i)=>{
      const d = new Date(); d.setDate(d.getDate()-(6-i));
      return d.toISOString().slice(0,10);
    });
    const total = DATA.trainees.length || 1;
    const pcts = days.map(d=>{
      const rec = DATA.attendance[d];
      if(!rec) return null;
      const present = Object.values(rec).filter(s=>s==="P").length;
      return Math.round((present/total)*100);
    });
    _chartAttendance = new Chart(c2, {
      type:"bar",
      data:{
        labels:days.map(d=>d.slice(5)),
        datasets:[{label:"% Present", data:pcts, backgroundColor:"#123a5e"}]
      },
      options:{scales:{y:{beginAtZero:true,max:100}}, plugins:{legend:{display:false}}}
    });
  }
};

